export function Encapsulation({
  componentName = "{{componentName}}",
  publicProp = "{{publicProp}}",
  revealInternals = {{revealInternals}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 300, boxSizing: "border-box", border: "2px solid #24143020" }}>
      <p style={{ margin: "0 0 4px", fontFamily: "ui-monospace, monospace", fontSize: 12, fontWeight: 700 }}>&lt;{componentName} {publicProp}="&hellip;" /&gt;</p>
      <p style={{ margin: 0, fontSize: 11, color: "#24143099" }}>public API &mdash; the only thing callers can see</p>
      {revealInternals && (
        <div style={{ marginTop: 14, padding: 12, border: `2px dashed ${accent}`, borderRadius: 8, background: "#24143008" }}>
          <p style={{ margin: "0 0 8px", fontSize: 10, color: "#24143099", textTransform: "uppercase", letterSpacing: ".04em" }}>private, inside the component</p>
          <code style={{ display: "block", fontFamily: "ui-monospace, monospace", fontSize: 11, marginBottom: 4 }}>isOpen = false</code>
          <code style={{ display: "block", fontFamily: "ui-monospace, monospace", fontSize: 11, marginBottom: 4 }}>hoverIndex = -1</code>
          <code style={{ display: "block", fontFamily: "ui-monospace, monospace", fontSize: 11, marginBottom: 4 }}>listboxRef</code>
        </div>
      )}
    </div>
  );
}
